SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_898
WHERE it2.id = non_leaf_898.pi_info_type_id AND (pi.info ILIKE '%may%') AND (it1.id IN ('16')) AND it1.id = non_leaf_898.mi1_info_type_id AND (mi1.info ILIKE '%den%') AND (it2.id IN ('23')) AND (kt.kind IN ('episode','tv mini series','tv series','video game','video movie')) AND (rt.role IN ('actor','cinematographer','composer','director','editor','guest','miscellaneous crew','producer','production designer'));